import sys
from collections import defaultdict

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
        m = int(next(iterator))
    except StopIteration:
        return

    degree = [0] * (n + 1)
    adj = defaultdict(set)

    for _ in range(m):
        u = int(next(iterator))
        v = int(next(iterator))
        degree[u] += 1
        degree[v] += 1
        if u != v:
            adj[u].add(v)
            adj[v].add(u)

    visited = [False] * (n + 1)
    components = []

    def dfs(start_node):
        stack = [start_node]
        comp_nodes = []
        while stack:
            node = stack.pop()
            if visited[node]:
                continue
            visited[node] = True
            comp_nodes.append(node)
            for neighbor in adj[node]:
                if not visited[neighbor]:
                    stack.append(neighbor)
        return comp_nodes

    for i in range(1, n + 1):
        if not visited[i]:
            comp = dfs(i)
            if comp:
                components.append(comp)

    odd_degree_count = 0
    isolated_components_with_edges = 0
    component_with_1 = None

    for comp in components:
        has_edge = False
        odd_cnt = 0
        for node in comp:
            if degree[node] > 0:
                has_edge = True
            if degree[node] % 2 == 1:
                odd_cnt += 1

        if has_edge:
            isolated_components_with_edges += 1
            odd_degree_count += odd_cnt

        if 1 in comp:
            component_with_1 = comp

    if m == 0:
        print(0)
        return

    if odd_degree_count == 0:
        if isolated_components_with_edges == 1:
            print(0)
        else:
            print(isolated_components_with_edges - 1)
    else:
        ans = odd_degree_count // 2
        if isolated_components_with_edges > 1:
            ans += isolated_components_with_edges - 1
        print(ans)

if __name__ == "__main__":
    main()
